package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net/http"
	"strings"
	"sync"
)

var (
	encryptionKey []byte
	ledger        sync.Map
)

func init() {
	key := make([]byte, 32)
	if _, err := rand.Read(key); err != nil {
		log.Fatal(err)
	}
	encryptionKey = key
}

func encryptData(plaintext string) (string, error) {
	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return "", err
	}
	aesGCM, err := cipher.NewGCM(block)
	if err != nil {
		return "", err
	}
	nonce := make([]byte, aesGCM.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return "", err
	}
	ciphertext := aesGCM.Seal(nonce, nonce, []byte(plaintext), nil)
	return base64.StdEncoding.EncodeToString(ciphertext), nil
}

func decryptData(encoded string) (string, error) {
	ciphertext, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		return "", err
	}
	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return "", err
	}
	aesGCM, err := cipher.NewGCM(block)
	if err != nil {
		return "", err
	}
	nonceSize := aesGCM.NonceSize()
	if len(ciphertext) < nonceSize {
		return "", fmt.Errorf("ciphertext too short")
	}
	nonce, ciphertext := ciphertext[:nonceSize], ciphertext[nonceSize:]
	plaintext, err := aesGCM.Open(nil, nonce, ciphertext, nil)
	if err != nil {
		return "", err
	}
	return string(plaintext), nil
}

func sanitizeField(input string) string {
	input = strings.ReplaceAll(input, "\r\n", "")
	input = strings.ReplaceAll(input, "\r", "")
	input = strings.ReplaceAll(input, "\n", "")
	return input
}

func buildLedgerEntry(txID, merchantID, amount, currency string) string {
	return fmt.Sprintf("TX-ID: %s\r\nMerchant: %s\r\nAmount: %s %s\r\nStatus: pending",
		txID, merchantID, amount, currency)
}

func generateTxID() (string, error) {
	b := make([]byte, 16)
	if _, err := io.ReadFull(rand.Reader, b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func processPayment(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	merchantID := r.FormValue("merchant_id")
	amount := r.FormValue("amount")
	currency := r.FormValue("currency")

	if merchantID == "" || amount == "" || currency == "" {
		http.Error(w, "Missing required fields", http.StatusBadRequest)
		return
	}

	// Sanitize all user-controlled fields against CRLF
	merchantID = sanitizeField(merchantID)
	amount = sanitizeField(amount)

	// Currency is validated against a known set
	validCurrencies := map[string]bool{"USD": true, "EUR": true, "GBP": true}
	normalizedCurrency := strings.ToUpper(strings.TrimSpace(currency))
	if !validCurrencies[normalizedCurrency] {
		http.Error(w, "Invalid currency", http.StatusBadRequest)
		return
	}

	txID, err := generateTxID()
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	entry := buildLedgerEntry(txID, merchantID, amount, normalizedCurrency)

	encrypted, err := encryptData(entry)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}

	ledger.Store(txID, encrypted)

	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprintf(w, "Transaction %s recorded\n", txID)
}

func viewTransaction(w http.ResponseWriter, r *http.Request) {
	txID := r.URL.Query().Get("tx_id")
	if txID == "" {
		http.Error(w, "Missing tx_id", http.StatusBadRequest)
		return
	}

	val, ok := ledger.Load(txID)
	if !ok {
		http.Error(w, "Transaction not found", http.StatusNotFound)
		return
	}

	decrypted, err := decryptData(val.(string))
	if err != nil {
		http.Error(w, "Decryption error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprint(w, decrypted)
}

func approveTransaction(w http.ResponseWriter, r *http.Request) {
	txID := r.URL.Query().Get("tx_id")
	if txID == "" {
		http.Error(w, "Missing tx_id", http.StatusBadRequest)
		return
	}

	val, ok := ledger.Load(txID)
	if !ok {
		http.Error(w, "Transaction not found", http.StatusNotFound)
		return
	}

	decrypted, err := decryptData(val.(string))
	if err != nil {
		http.Error(w, "Decryption error", http.StatusInternalServerError)
		return
	}

	updated := strings.Replace(decrypted, "Status: pending", "Status: approved", 1)

	encrypted, err := encryptData(updated)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}

	ledger.Store(txID, encrypted)
	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprintf(w, "Transaction %s approved\n", txID)
}

func main() {
	http.HandleFunc("/pay", processPayment)
	http.HandleFunc("/view", viewTransaction)
	http.HandleFunc("/approve", approveTransaction)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
